parameters.jsCode:
// ساخت فایل Markdown با تاریخ شمسی
const out = $input.first().json.output;
const parts = new Intl.DateTimeFormat('en-US-u-ca-persian-nu-latn', { timeZone: 'Asia/Tehran', year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(new Date());
const g = t => parts.find(p => p.type === t)?.value || '';
const iso = `${g('year')}-${g('month')}-${g('day')}`;
const faDate = new Intl.DateTimeFormat('fa-IR-u-ca-persian', { timeZone: 'Asia/Tehran', dateStyle: 'full' }).format(new Date());
const transcript = $('Groq Whisper (رایگان)').first().json.text || '';
const slug = (out.title || 'jalase').replace(/["'`«»<>:/\|?*#%{}\[\]]/g, '').trim().replace(/\s+/g, '-').slice(0, 60);
const md = `---
title: "${out.title}"
date_jalali: ${iso}
type: meeting-minutes
agent: Dabira
---

# ${out.title}

**📅 ${faDate}**

> ${out.summary}

## صورت‌جلسه

${out.minutes}

---

## متن کامل جلسه (پیاده‌سازی)

${transcript}
`;
return [{ json: { md, fileName: `${iso}-${slug}.md`, title: out.title, summary: out.summary, chatId: $('Telegram Trigger').first().json.message.chat.id } }];

